if (args[0] === "on") {
const roll = await new Roll(args[1] || 7).evaluate();
const distance =  roll.total;

// ⚠️ Vérifie qu'il y a une cible sélectionnée
const target = game.user.targets.first();
if (!target) {
  ui.notifications.warn("Aucune cible sélectionnée !");
  return;
}
// Position du token de départ
const startX = token.center.x;
const startY = token.center.y;

// Position de la cible
const targetX = target.center.x;
const targetY = target.center.y;

// Vecteur direction normalisé
const dx = targetX - startX;
const dy = targetY - startY;
const len = Math.hypot(dx, dy);
const dirX = dx / len;
const dirY = dy / len;

// Conversion distance en pixels
const gridSize = canvas.grid.size;
const distPx = distance * gridSize; // 1 case = 1 grille

// Nouvelle position
const newPos = {
  x: startX + dirX * distPx,
  y: startY + dirY * distPx
};
console.log(newPos)

// Séquence de téléportation
new Sequence()
  .effect()
    .from(token)
    .fadeIn(50)
    .duration(550)
    .fadeOut(250)
    .filter("Blur")
    .elevation(0)
  .effect()
    .file("jb2a.chain_lightning.secondary.blue")
    .atLocation(token)
    .stretchTo(newPos)
    .elevation(0)
  .wait(100)
  .animation()
    .on(token)
    .teleportTo(newPos)
    .snapToGrid()
    .waitUntilFinished()
  .effect()
    .file("jb2a.static_electricity.03.blue")
    .atLocation(newPos)
    .scaleToObject()
  .play();
}
